def num_squares(n):
    def helper(remaining):
        if remaining == 0:
            return 0
        best = float('inf')
        j = 1
        while j * j <= remaining:
            best = min(best, 1 + helper(remaining - j * j))   # no caching, recomputes shared subproblems
            j += 1
        return best
    return helper(n)

